ía Bucal y Maxilofacial'] as $specialty):?><option value="<?=h($specialty)?>" <?=$value===$specialty?'selected':''?>><?=h($specialty)?></option><?php endforeach?></select><?php else:?><input id="<?=h($f)?>" name="<?=h($f)?>" type="<?=h($spec[1])?>" value="<?=h($value)?>" <?=is_int($spec[2])?'maxlength="'.$spec[2].'"':''?> <?=in_array($f,['Diagnostico','Tratamiento'],true)?'':'required'?> <?php if($f==='DNI'): ?>pattern="[0-9]{8}" inputmode="numeric" title="Ingresa un DNI de 8 dígitos"<?php elseif($f==='Telefono'): ?>pattern="[0-9+()\-\s]{7,15}" title="Ingresa un teléfono válido de 7 a 15 caracteres"<?php elseif($spec[1]==='number'): ?>min="0.01" step="0.01"<?php endif?>><?php endif?></div><?php endforeach?></div><div class="form-actions"><button class="button button-primary" type="submit">Guardar</button><button class="button button-outline" type="button" data-close-record-dialog>Cancelar</button></div></form></section></dialog>
